package edu.klh.soa.workflow;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Component public class WorkflowConsumer {private final ConsumedRepository repo;public WorkflowConsumer(ConsumedRepository r){repo=r;} @KafkaListener(topics="soa.s02.t17.events",groupId="pharmacy-workflow",containerFactory="kafkaListenerContainerFactory") @Transactional public void consume(Map<String,Object> e){try{String id=str(e,"eventId"),lot=str(e,"lotCode"),agg=str(e,"aggregateId"),corr=str(e,"correlationId");if(!Objects.equals(lot,agg)||!Objects.equals(e.get("schemaVersion"),1)&&!Objects.equals(String.valueOf(e.get("schemaVersion")),"1")||!e.containsKey("occurredAt")||!e.containsKey("productCode")||!e.containsKey("reason"))throw new IllegalArgumentException("invalid event schema");if(repo.existsById(id))return;ConsumedEvent ce=new ConsumedEvent(id,agg,corr);ce.status="QUARANTINED";repo.save(ce);}catch(Exception ex){throw ex;}}private String str(Map<String,Object> m,String k){Object v=m.get(k);if(v==null||v.toString().isBlank())throw new IllegalArgumentException("missing "+k);return v.toString();}}
